package com.supermarkettracker.infrastructure.persistence.entity;
import com.supermarkettracker.domain.model.enums.StatusSessaoCaixa;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="sessao_caixa") public class SessaoCaixaEntity { @Id public UUID id; @Column(name="caixa_id",nullable=false) public UUID caixaId; @Column(name="usuario_abertura_id",nullable=false) public UUID usuarioAberturaId; @Column(name="usuario_fechamento_id") public UUID usuarioFechamentoId; @Column(name="aberto_em",nullable=false) public Instant abertoEm; @Column(name="fechado_em") public Instant fechadoEm; @Column(name="valor_abertura",nullable=false,precision=14,scale=2) public BigDecimal valorAbertura; @Column(name="valor_fechamento_informado",precision=14,scale=2) public BigDecimal valorFechamentoInformado; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) public StatusSessaoCaixa status; public String observacao; public SessaoCaixaEntity() {} }
